package com.brasa.restaurant.model;import jakarta.persistence.*;@Entity@Table(name="restaurantes")public class Restaurante extends BaseEntity{@Column(nullable=false)private String nome;@Column(nullable=false,unique=true)private String slug;private String logoUrl;private String corPrimaria="#e11d48";private String corDestaque="#ea580c";private boolean ativo=true;public String getNome(){return nome;}public void setNome(String v){nome=v;}public String getSlug(){return slug;}public void setSlug(String v){slug=v;}public String getLogoUrl(){return logoUrl;}public void setLogoUrl(String v){logoUrl=v;}public String getCorPrimaria(){return corPrimaria;}public void setCorPrimaria(String v){corPrimaria=v;}public String getCorDestaque(){return corDestaque;}public void setCorDestaque(String v){corDestaque=v;}public boolean isAtivo(){return ativo;}public void setAtivo(boolean v){ativo=v;}}
